  var handleList = function handleList(items, q) {
  let list = [...items];
  const cat = q.get('filters[worship_category][category][$eq]');
  if (cat) list = list.filter((x) => x.worship_category?.category === cat);
  const ors = [...q.entries()].filter(([k]) => k.startsWith('filters[$or]')).map(([k, v]) => [k.match(/\]\[(\w+)\]\[\$contains\]/)?.[1], v]);
  if (ors.length) list = list.filter((x) => ors.some(([f, v]) => f && String(x[f] ?? '').includes(v)));
  const sort = q.get('sort');
  if (sort) {
    const [field, dir] = sort.split(':');
    list.sort((a, b) => String(a[field]).localeCompare(String(b[field])) * (dir === 'desc' ? -1 : 1));
  }
  const limit = Number(q.get('pagination[limit]')) || 0;
  const pageSize = limit || Number(q.get('pagination[pageSize]')) || 25;
  const page = Number(q.get('pagination[page]')) || 1;
  const total = list.length;
  const data = list.slice((page - 1) * pageSize, page * pageSize);
  return { data, meta: { pagination: { page, pageSize, pageCount: Math.max(1, Math.ceil(total / pageSize)), total } } };
};
  var realFetch = window.fetch.bind(window);
  function json(body, status) {
    return Promise.resolve(new Response(JSON.stringify(body), { status: status || 200, headers: { 'Content-Type': 'application/json' } }));
  }
  window.fetch = function (input, init) {
    var raw = typeof input === 'string' ? input : input && input.url;
    var url;
    try { url = new URL(raw, location.href); } catch (e) { return realFetch(input, init); }
    var m = url.pathname.match(/\/mock\/api\/([a-z-]+)(?:\/([^/]+))?\/?$/);
    if (!m) return realFetch(input, init);
    var col = collections[m[1]];
    if (!col) return json({ data: null, error: { status: 404 } }, 404);
    if (col.single) return json({ data: col.single, meta: {} });
    if (m[2]) {
      var id = decodeURIComponent(m[2]);
      var item = col.items.find(function (x) { return x.documentId === id || String(x.id) === id; });
      return item ? json({ data: item, meta: {} }) : json({ data: null, error: { status: 404 } }, 404);
    }
    return json(handleList(col.items, url.searchParams));
  };
